getEnclosingRange() {
        let result;
        const model = this.g.getModel();
        for (const decorationId of this.c.values()) {
            const placeholderRange = model.getDecorationRange(decorationId) ?? undefined;
            if (!result) {
                result = placeholderRange;
            }
            else {
                result = result.plusRange(placeholderRange);
            }
        }
        return result;
    }
